"""Kaggle-only deterministic replay. Embedded bytes are frozen, public, synthetic inputs."""
import base64
import hashlib
import io
import json
import os
from pathlib import Path, PurePosixPath
import shutil
import subprocess
import sys
import tarfile
import urllib.request

FILES = {'harness/replay_synthetic.py': {'sha256': '32b3ab8413fcb51d1133cb2e34f1ee0d864a0f8164849df49f69c1363c55272e', 'base64': ''}, 'harness/synthetic/manifest.json': {'sha256': '0e1047810af095864e94b3aa17b4f8c0812a4a4b32a7b13f506e65aeb4b3b763', 'base64': ''}, 'harness/synthetic/reference-cases.json': {'sha256': 'aabe0f8b121f32a5eda7795dfe730f70993829a30b18c1857974b5cdf4e6fcd0', 'base64': ''}, 'harness/source/package.json': {'sha256': '0f183be3df9c6226fb662731461fc921d001ebc2372bf07e57528fbfaa453de2', 'base64': 'eyJuYW1lIjogIm9yYml0LWNhbXBhaWduLXYyIiwgInByaXZhdGUiOiB0cnVlLCAidHlwZSI6ICJtb2R1bGUiLCAiZGVwZW5kZW5jaWVzIjogeyJlc2J1aWxkIjogIjAuMjUuMTIifX0='}, 'harness/source/tools/engine-jsonl.ts': {'sha256': 'a07c83552b9c1b6450814819ecf0f9392f698f386e3c10bc06917edb4f7a9b39', 'base64': ''}, 'harness/source/packages/evidence-review/src/index.ts': {'sha256': '1ef6ca28cf3da9001708d45a64b39c65192523584fd383d3a701010926cfa937', 'base64': ''}, 'harness/source/packages/evidence-review/src/classification.ts': {'sha256': '230a5f494e64f86428aa3f26b6cfe6ab0d42c78d47f758419bfe76f7f22019ae', 'base64': ''}, 'harness/source/packages/evidence-review/src/relations.ts': {'sha256': 'd5da24352b213c55cede9559e2faa48b3b8451c57a3257b882c77ff82ee495a4', 'base64': ''}}
NODE_URL = "https://nodejs.org/dist/v22.20.0/node-v22.20.0-linux-x64.tar.xz"
NODE_SHA256 = "00bbd05e306ea68b6e13e17360d0e2f680b493ef95f2fea1c4296ff7437530bc"
WORK = Path("/kaggle/working/orbit-synthetic-replay")


def invoke(args, *, cwd, env, timeout):
    completed = subprocess.run(args, cwd=cwd, env=env, capture_output=True,
                               text=True, timeout=timeout)
    if completed.returncode:
        raise RuntimeError(f"Command failed ({completed.returncode}): "
                           + completed.stderr[-1500:])
    return completed


def runtime():
    node, npm = shutil.which("node"), shutil.which("npm")
    env = dict(os.environ)
    if node and npm:
        version = invoke([node, "--version"], cwd=WORK, env=env, timeout=10).stdout.strip()
        if int(version.lstrip("v").split(".")[0]) < 20:
            raise RuntimeError("Node >=20 is required; installed older runtime is not silently replaced.")
        return node, [npm], env, version
    with urllib.request.urlopen(NODE_URL, timeout=45) as response:
        archive = response.read(64 * 1024 * 1024 + 1)
    if len(archive) > 64 * 1024 * 1024 or hashlib.sha256(archive).hexdigest() != NODE_SHA256:
        raise RuntimeError("Official Node archive SHA-256 mismatch.")
    destination = WORK / "runtime"
    prefix = "node-v22.20.0-linux-x64/"
    # Only regular files from Node and npm are copied; no archive links or arbitrary paths.
    with tarfile.open(fileobj=io.BytesIO(archive), mode="r:xz") as package:
        for member in package.getmembers():
            if not member.isfile() or not member.name.startswith(prefix):
                continue
            name = member.name[len(prefix):]
            if name != "bin/node" and not name.startswith("lib/node_modules/npm/"):
                continue
            relative = PurePosixPath(name)
            if relative.is_absolute() or ".." in relative.parts or member.size > 150 * 1024 * 1024:
                raise RuntimeError("Unexpected file in verified Node archive.")
            target = destination.joinpath(*relative.parts)
            target.parent.mkdir(parents=True, exist_ok=True)
            target.write_bytes(package.extractfile(member).read())
    executable = destination / "bin/node"
    executable.chmod(0o700)
    npm_cli = destination / "lib/node_modules/npm/bin/npm-cli.js"
    if not npm_cli.is_file():
        raise RuntimeError("npm CLI missing from verified Node archive.")
    env["PATH"] = str(executable.parent) + os.pathsep + env.get("PATH", "")
    version = invoke([str(executable), "--version"], cwd=WORK, env=env, timeout=10).stdout.strip()
    return str(executable), [str(executable), str(npm_cli)], env, version


def main():
    if os.name != "posix" or not Path("/kaggle/working").is_dir():
        raise RuntimeError("This entry point runs only in Kaggle; no local replay is authorized here.")
    WORK.mkdir(parents=True, exist_ok=True)
    for name, item in FILES.items():
        relative = PurePosixPath(name)
        if relative.is_absolute() or ".." in relative.parts:
            raise RuntimeError("Unsafe embedded path.")
        content = base64.b64decode(item["base64"], validate=True)
        if hashlib.sha256(content).hexdigest() != item["sha256"]:
            raise RuntimeError("Embedded input SHA-256 mismatch: " + name)
        target = WORK.joinpath(*relative.parts)
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_bytes(content)
    node, npm, env, version = runtime()
    source = WORK / "harness/source"
    # Pin dependency version; suppress lifecycle scripts and keep cache/lock writes in WORK.
    invoke(npm + ["install", "--prefix", str(source), "--ignore-scripts", "--no-audit",
                  "--no-fund", "--package-lock=false", "--cache", str(WORK / "npm-cache")],
           cwd=WORK, env=env, timeout=180)
    esbuild = source / "node_modules/esbuild/bin/esbuild"
    esbuild_version = invoke([node, str(esbuild), "--version"], cwd=source, env=env,
                             timeout=15).stdout.strip()
    if esbuild_version != "0.25.12":
        raise RuntimeError("Unexpected esbuild version: " + esbuild_version)
    invoke([node, str(esbuild), str(source / "tools/engine-jsonl.ts"), "--bundle",
            "--platform=node", "--format=esm", "--outfile=" + str(source / "engine-jsonl.mjs")],
           cwd=source, env=env, timeout=60)
    # replay_synthetic.py invokes `node`; make the selected runtime discoverable explicitly.
    env["PATH"] = str(Path(node).parent) + os.pathsep + env.get("PATH", "")
    output = WORK / "results/synthetic-replay.json"
    invoke([sys.executable,
                     str(WORK / "harness/replay_synthetic.py"),
                     "--corpus", str(WORK / "harness/synthetic"), "--output", str(output)],
                    cwd=WORK, env=env, timeout=120)
    result = json.loads(output.read_text(encoding="utf-8"))
    summary = result["summary"]
    expected = {"questions": 36, "invariantsTotal": 108, "relationTotal": 18}
    for engine in ("baseline", "n", "p"):
        for metric, count in expected.items():
            if summary[engine][metric] != count:
                raise RuntimeError(f"Incomplete replay: {engine}/{metric}.")
    failures = [{"case": row["caseId"], "engine": row["engine"], "operation": row["operation"]}
                for row in result["rows"] if not row["pass"]]
    passed = all(row["correct"] == row["questions"]
                 and row["invariantsPassed"] == row["invariantsTotal"]
                 and row["relationPassed"] == row["relationTotal"] for row in summary.values())
    receipt = {"format": "orbit-kaggle-synthetic-replay-v1", "status": "passed" if passed else "failed",
               "modelCalls": 0, "nodeVersion": version, "esbuildVersion": "0.25.12",
               "decisions": 108, "metamorphicChecks": 324, "relationChecks": 54,
               "summary": summary, "failures": failures,
               "inputs": {name: item["sha256"] for name, item in FILES.items()},
               "resultSha256": hashlib.sha256(output.read_bytes()).hexdigest(),
               "compiledEngineSha256": hashlib.sha256((source / "engine-jsonl.mjs").read_bytes()).hexdigest(),
               "limitations": result["limitations"]}
    (output.parent / "execution-receipt.json").write_text(json.dumps(receipt, indent=2) + "\n", encoding="utf-8")
    print(json.dumps(receipt, indent=2))
    # A successful subprocess alone is insufficient: failed checks remain visible and fail this cell.
    if not passed or failures:
        raise AssertionError("Replay checks failed; retain detailed results and receipt as observations.")
    return receipt


if __name__ == "__main__":
    main()
